    "_Followed by {named} and %n other you follow_::_Followed by {named} and %n others you follow_" : ["Suivi par {named} et %n autres personnes que vous suivez", "Suivi par {named} et %n autres personnes que vous suivez", "Suivi par {named} et %n autres personnes que vous suivez"],
